{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "Imipramine, a lipophilic tricyclic antidepressant with a tertiary aminopropyl side chain, has an absolute oral bioavailability of 47.3 ± 21.4% in humans, supporting F ≥20% for the query's similar lipophilic tertiary-amine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Fentanyl, an N-phenyl-substituted basic amine/amide with a phenethylpiperidine, has an absolute oral bioavailability of 32% after swallowed oral solution, supporting high oral F for the query's N-phenyl/basic amine lipophilic structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Amitriptyline, a tricyclic antidepressant with a dimethylaminopropylidene chain, shows human oral bioavailability of 30–64%, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Delapril, which contains an indanyl group, has absolute oral bioavailability >55% in humans, supporting that the indanyl moiety in the query is compatible with high oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Oxybutynin, a diethylamino-containing ester analogue, has absolute oral bioavailability of only 6.2%, providing contradictory low-F evidence; however, the query lacks the ester linkage responsible for oxybutynin's extensive first-pass hydrolysis.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C46"],
      "claim": "Rotigotine, an aminotetralin with a phenolic OH, has low oral bioavailability due to first-pass metabolism; this low-F evidence is only weakly transferable because the query lacks the phenolic group.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a lipophilic tertiary diamine with no ester, amide, or phenol liability. The most relevant analogues with similar tertiary-amine/lipophilic aromatic character—imipramine, amitriptyline, fentanyl, and delapril—show human oral F ≥30%, while the low-F analogues (oxybutynin, rotigotine) owe their low F to ester/phenol groups absent in the query. Therefore F ≥20% is better supported.",
  "evidence_gaps": [
    "No direct human absolute oral bioavailability measurement exists for the query molecule.",
    "All evidence comes from analogues with low-to-moderate Morgan similarity, so transferability is limited.",
    "No data are available on first-pass metabolism or transporter effects specific to the diethylaminopropyl-N-phenyl-indanamine scaffold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

